1: "use client";
2: 
3: import type { BashAction } from "@repo/shared";
4: import { ExpandableSummary } from "./expandable-summary";
5: 
6: interface BashPartProps {
7:   action: BashAction;
8: }
9: 
10: export function BashPart({ action }: BashPartProps) {
11:   const firstLine = action.command.split("\n")[0] ?? "";
12:   return (
13:     <ExpandableSummary
14:       summary={<CommandSummary command={firstLine} />}
15:       status={typeof action.exitCode === "number" && action.exitCode !== 0 ? `exit ${action.exitCode}` : undefined}
16:       detail={<BashOutput action={action} />}
17:       disabled={action.output === undefined || action.output.length === 0}
18:     />
19:   );
20: }
21: 
22: function CommandSummary({ command }: { command: string }) {
23:   return (
24:     <span className="inline-flex min-w-0 items-baseline gap-2 font-mono">
25:       <span className="shrink-0 w-4 text-center text-current" aria-hidden="true">$</span>
26:       <span className="min-w-0 truncate">{command || "(no command)"}</span>
27:     </span>
28:   );
29: }
30: 
31: function BashOutput({ action }: { action: BashAction }) {
32:   return (
33:     <>
34:       {action.output !== undefined && action.output.length > 0 && (
35:         <pre className="max-h-72 overflow-auto rounded-md border border-border bg-background px-3 py-2 font-mono text-xs text-foreground-muted whitespace-pre-wrap wrap-break-word">
36:           {action.output}
37:         </pre>
38:       )}
39:     </>
40:   );
41: }
42: 
43: function PromptIcon() {
44:   return <span className="font-mono text-[13px] leading-none">$</span>;
45: }
46: 
47: interface BashGroupPartProps {
48:   actions: BashAction[];
49: }
50: 
51: export function BashGroupPart({ actions }: BashGroupPartProps) {
52:   return (
53:     <ExpandableSummary
54:       icon={<PromptIcon />}
55:       summary={`Ran ${actions.length} commands`}
56:       detail={
57:         <div className="my-1 space-y-1 pl-3">
58:           {actions.map((action, index) => (
59:             <ExpandableSummary
60:               key={index}
61:               summary={<CommandSummary command={action.command.split("\n")[0] ?? ""} />}
62:               detail={<BashOutput action={action} />}
63:               disabled={action.output === undefined || action.output.length === 0}
64:               className="my-0"
65:             />
